"""Generate compact raw CSVs, an auditable Markdown report and filtered review page."""
import collections,csv,datetime,html,json,math,pathlib,shutil,statistics
import common as c
p=c.arguments(__doc__);p.add_argument('--destination',type=pathlib.Path,required=True);a=p.parse_args();c.setup(a.work);dest=a.destination.resolve();dest.mkdir(exist_ok=True,parents=True)
runs=c.readlines(c.WORK/'runs.jsonl');gates=c.readlines(c.WORK/'performance-gates.jsonl');correct=c.readlines(c.WORK/'correctness.jsonl');cases=json.loads((c.WORK/'cases.json').read_text()) if (c.WORK/'cases.json').exists() else []
caseby={q['id']:q for q in cases};groups=collections.defaultdict(list)
for r in runs:groups[(r['case'],r['entry'],r['pass'])].append(r)
pg={(r['case'],r['entry']):r for r in gates};rows=[]
for case in cases:
 base=groups[(case['id'],'zig','speed')];base=[r['wall_seconds'] for r in base if r['valid']]
 basem=groups[(case['id'],'zig','memory')];basem=[r['tree_peak_rss_bytes'] for r in basem if r['valid']]
 for id in c.IDS:
  speed=groups[(case['id'],id,'speed')];memory=groups[(case['id'],id,'memory')]
  times=[r['wall_seconds'] for r in speed if r['valid']]
  mem=[r['tree_peak_rss_bytes'] for r in memory if r['valid']]
  if not times:continue
  median=statistics.median(times);bmed=statistics.median(base) if base else None
  speedup=bmed/median if bmed else None
  # Conservative tie: at least 5% difference AND disjoint observed ranges.
  label='baseline' if id=='zig' else 'pending'
  if id!='zig' and base:
   if abs(speedup-1)<.05 or (max(min(times),min(base))<=min(max(times),max(base))):label='tie / overlapping variation'
   else:label='faster observed' if speedup>1 else 'slower observed'
  m=statistics.median(mem) if mem else None;bm=statistics.median(basem) if basem else None
  gate=pg.get((case['id'],id),{})
  rows.append(dict(case=case['id'],entry=id,profile='node-44k-float' if id=='node' else 'zig-48k',workload=case['workload'],input_format=case['input_format'],output_format=case['output_format'],ratio=case['ratio'],publication=case['publication'],input_seconds=case['input_seconds'],repetitions=len(times),median_seconds=median,min_seconds=min(times),max_seconds=max(times),q1_seconds=float(__import__('numpy').percentile(times,25)),q3_seconds=float(__import__('numpy').percentile(times,75)),throughput_input_seconds_per_second=case['input_seconds']/median,zig_median_seconds=bmed,speedup_vs_zig=speedup,speed_verdict=label if id!='node' else 'different profile; '+label,memory_repetitions=len(mem),tree_peak_rss_bytes=m,memory_ratio_vs_zig=m/bm if m and bm else None,memory_delta_vs_zig_bytes=m-bm if m and bm else None,process_tree_cpu_seconds_median=statistics.median(r['cpu_user_seconds']+r['cpu_system_seconds'] for r in speed if r['valid']),output_bytes=gate.get('evidence',{}).get('output_bytes'),first_launch_seconds=gate.get('first_launch',{}).get('wall_seconds'),sampling_interval_median_ms=statistics.median(r['sampling_interval_seconds_median']*1000 for r in memory if r.get('sampling_interval_seconds_median')) if any(r.get('sampling_interval_seconds_median') for r in memory) else None))
def writecsv(name,items,fields=None):
 if not items:return
 keys=fields or list(items[0]);
 with (dest/name).open('w',newline='') as f:
  out=csv.DictWriter(f,fieldnames=keys,extrasaction='ignore');out.writeheader();out.writerows(items)
writecsv('cases.csv',rows)
rawfields=['case','entry','pass','repetition','order_index','unix_time','valid','returncode','wall_seconds','cpu_user_seconds','cpu_system_seconds','output_bytes','tree_peak_rss_bytes','samples','sampling_interval_seconds_median','sampling_interval_seconds_max','max_single_process_sampled_rss_bytes','sum_per_process_maxima_bytes','sampled_cpu_lower_bound_seconds']
writecsv('runs.csv',runs,rawfields)
compact=[dict(entry=q['entry'],gate=q['gate'],category=q['category'],status=q['status'],evidence=json.dumps({k:v for k,v in q['evidence'].items() if k!='trace'}) if isinstance(q['evidence'],dict) else str(q['evidence'])) for q in correct]
writecsv('correctness.csv',compact)
writecsv('performance-gates.csv',[dict(case=q['case'],entry=q['entry'],status=q['status'],error=q.get('error',''),evidence=json.dumps(q.get('evidence',{})),first_launch_seconds=q.get('first_launch',{}).get('wall_seconds')) for q in gates])
for name in ['config.json','builds.json','fixtures.json']:
 if (c.WORK/name).exists():shutil.copyfile(c.WORK/name,dest/name)
environment=json.loads((c.WORK/'environment.json').read_text());environment.pop('load',None)
(dest/'environment.json').write_text(json.dumps(environment,indent=2))
# Process identities/breakdowns are required to audit concurrent tree RSS. Retain
# all memory rows, excluding stderr and absolute command lines.
(dest/'memory-processes.json').write_text(json.dumps([{k:v for k,v in r.items() if k not in ['stderr']} for r in runs if r['pass']=='memory'],separators=(',',':')))
summary=[]
for id in c.IDS:
 required=[q for q in correct if q['entry']==id and q['category']=='required'];boundary=[q for q in correct if q['entry']==id and q['category']=='boundary']
 rr=[q for q in rows if q['entry']==id];ratios=[q['speedup_vs_zig'] for q in rr if q['speedup_vs_zig']];mem=[q['memory_ratio_vs_zig'] for q in rr if q['memory_ratio_vs_zig']]
 summary.append(dict(entry=id,required_pass=sum(q['status']=='PASS' for q in required),required_total=len(required),boundary_pass=sum(q['status']=='PASS' for q in boundary),boundary_total=len(boundary),cases=len(rr),complete_speed_cases=sum(q['repetitions']>=7 for q in rr),memory_cases=sum(q['memory_repetitions']>0 for q in rr),geomean_speedup=math.exp(statistics.mean(math.log(v) for v in ratios)) if ratios else None,median_memory_ratio=statistics.median(mem) if mem else None,faster_cases=sum(q['speed_verdict']=='faster observed' for q in rr),slower_cases=sum(q['speed_verdict']=='slower observed' for q in rr),ties=sum(q['speed_verdict']=='tie / overlapping variation' for q in rr)))
(dest/'summary.json').write_text(json.dumps(summary,indent=2))
complete=all(s['complete_speed_cases']==192 and s['memory_cases']==192 for s in summary)
def fmt(v,n=3):return 'pending' if v is None else f'{v:.{n}f}'
def table(headers,data):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join('---' for _ in headers)+'|',*['| '+' | '.join(str(v) for v in q)+' |' for q in data]])
md=['# Resample linked export comparison','',('Complete measurements.' if complete else 'Measurements are running; this page is provisional.'),'','## Correctness','',table(['Entry','Required gates','Boundary diagnostics','Complete speed cases','Memory cases'],[[s['entry'],f"{s['required_pass']}/{s['required_total']}",f"{s['boundary_pass']}/{s['boundary_total']}",f"{s['complete_speed_cases']}/192",f"{s['memory_cases']}/192"] for s in summary]),'', 'Boundary diagnostics are separate from ordinary correctness and performance. Reference-empty results never enter the speed ranking. Supported finite extensions beyond the reference are labeled separately.','', '### Named failures','']
for id in c.IDS:
 fails=[q for q in correct if q['entry']==id and q['status']=='FAIL']
 if fails:
  md += [f'**{id}**',*['- '+q['gate']+': '+str(q['evidence'].get('error',''))[:700] for q in fails],'']
md+=['## Matched-profile observations','','Zig is the pinned comparison denominator and has contract failures listed above. Its timings describe successful ordinary exports; they do not certify its safety. C/C++/Go/Rust are FFmpeg orchestration implementations, not new DSP algorithms. All five use the same primary filter graph and encoding profile.','',table(['Entry','Geometric mean Zig/candidate','Clear faster cases','Ties / overlap','Clear slower cases','Median memory/Zig'],[[s['entry'],fmt(s['geomean_speedup']),s['faster_cases'],s['ties'],s['slower_cases'],fmt(s['median_memory_ratio'])] for s in summary if s['entry']!='node']),'','The geometric mean weights each case equally. A clear speed observation requires a difference of at least 5% and disjoint observed min/max ranges. It is descriptive, not a causal or statistical confidence claim. See per-case medians, IQR, min/max, throughput, CPU, output sizes and RSS in cases.csv.','', '## Node profile comparison','','Node uses 44.1 kHz float WAV and lamejs 320 kbps MP3; Zig/new entries use 48 kHz PCM24 WAV and libmp3lame. These are different encoding and DSP workloads. Node numbers are observational and must not be included in an unqualified six-way same-workload ranking. Node also fsyncs its temporary before publication; the other entries do not promise fsync durability. No hidden transcode or baseline modification was applied.','']
node=summary[-1];md += [f"Node geometric mean Zig/Node time: {fmt(node['geomean_speedup'])}; median memory/ Zig: {fmt(node['median_memory_ratio'])}. Both have the profile/workload caveat above.",'','## Measurement and limits','','Each of 192 cases has one untimed warmup, at least seven speed repetitions in rotated order, and a separate memory pass. Timing includes startup, source validation, decode, DSP, encode, write, publication and process exit. Repetition output checks require a successful exit and the warmup output size; warmups/reference outputs are fully decoded for finite samples, duration and profile. No header-only or failed output is scored.','', 'RSS is the maximum sampled contemporaneous sum across the wrapper and recursive child tree, including C validators. A requested 2 ms wait follows each scan; achieved cadence is recorded. This is a sampled lower bound and can double-count shared mappings. It differs from max single-process RSS and from the sum of unrelated per-process maxima, both retained only for audit. CPU includes the kernel child usage across the command and a sampled process-by-process lower bound. Memory instrumentation never enters the speed medians.','', 'Processes are freshly launched for every export; caches are warm and never purged. First-launch times are retained separately; true disk-cold latency was not established. No physical listening or second-device access is implied. This report qualifies arm64 macOS 27.2 only; it does not establish Linux/Windows runtime or crash/power-loss safety.','', 'Research had other active sessions and a continuously busy one-core Python process at setup. They were preserved. Host load and swap are recorded at each case. Results describe this shared host and their observed spread, rather than an idle-machine maximum.','', 'Builds are outside timing. Build durations reflect local compiler/package caches and are not clean download times. The Node binary size is the runtime launcher; source/packages and shared runtime dependencies are separate deployment costs. Full toolchain, FFmpeg build configuration, executable hashes and source revisions are in environment.json, config.json and builds.json.','', '## Reproduce','','Use competition/harness/README.md for pinned checkout/build/run commands. Fixtures are generated once with seed 20261115; their hashes are in fixtures.json. Full logs, fixtures, binaries and JSONL stay in the task scratch directory. The compact raw repetition CSV and process memory breakdown accompany this report.','', '## Per-case results','','[Case table](cases.csv) · [Raw repetitions](runs.csv) · [Correctness evidence](correctness.csv) · [Performance qualification](performance-gates.csv) · [Memory process tree](memory-processes.json) · [Environment](environment.json)','']
(dest/'REPORT.md').write_text('\n'.join(md))
