h+='''const filters=[['entry','Entry'],['workload','Workload'],['input_format','Input'],['output_format','Output'],['ratio','Ratio'],['publication','Publication']];const controls={};for(const [key,label]of filters){let l=document.createElement('label');l.textContent=label;let s=document.createElement('select');s.setAttribute('aria-label',label);s.innerHTML='<option value="">All</option>';for(const v of [...new Set(rows.map(r=>String(r[key])))]){let o=document.createElement('option');o.value=v;o.textContent=v;s.append(o)}l.append(s);document.querySelector('#filters').append(l);controls[key]=s;s.onchange=render}function f(v,n=3){return v==null?'pending':Number(v).toFixed(n)}function render(){let rr=rows.filter(r=>filters.every(([k])=>!controls[k].value||String(r[k])===controls[k].value));document.querySelector('#count').textContent=rr.length+' entry/case measurements';let body=document.querySelector('#data');body.replaceChildren();for(let r of rr){let tr=document.createElement('tr');let cells=[r.case,r.entry,f(r.median_seconds),f(r.q1_seconds)+'–'+f(r.q3_seconds),f(r.min_seconds)+'–'+f(r.max_seconds),f(r.throughput_input_seconds_per_second,1),f(r.speedup_vs_zig),r.speed_verdict,r.tree_peak_rss_bytes==null?'pending':r.tree_peak_rss_bytes.toLocaleString(),f(r.memory_ratio_vs_zig),r.memory_delta_vs_zig_bytes==null?'pending':r.memory_delta_vs_zig_bytes.toLocaleString(),f(r.process_tree_cpu_seconds_median)];cells.forEach((v,i)=>{let td=document.createElement('td');td.textContent=v;if(i>1&&i!==7)td.className='num';tr.append(td)});body.append(tr)}}render();</script></body></html>'''
